import React, { useState, useEffect } from 'react';
import api from '../api';
import PreShiftForm from './PreShiftForm';
import MODReport from './MODReport';
import GroupResumeList from './GroupResumeList';

function CalendarView({ onDateSelect, userRole }) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [calendarData, setCalendarData] = useState({ daily: {}, weekly: {}, monthly: {} });
  const [preshiftDates, setPreshiftDates] = useState([]);
  const [modDates, setModDates] = useState([]);
  const [groupResumeDates, setGroupResumeDates] = useState({});
  const [viewMode, setViewMode] = useState('tasks'); // 'tasks', 'preshift', 'mod', or 'groupresumes'
  const [selectedDate, setSelectedDate] = useState(null);
  const [showPreShiftForm, setShowPreShiftForm] = useState(false);
  const [showMODReport, setShowMODReport] = useState(false);
  const [showGroupResumeList, setShowGroupResumeList] = useState(false);
  const [loading, setLoading] = useState(true);

  // Date selection mode for packets
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedDates, setSelectedDates] = useState([]);
  const [generatingPacket, setGeneratingPacket] = useState(false);

  const canCreatePacket = ['grand_admin', 'sales_admin', 'sales_employee'].includes(userRole);

  useEffect(() => {
    loadCalendarData();
  }, [currentDate, viewMode]);

  const loadCalendarData = async () => {
    setLoading(true);
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth() + 1;

    try {
      if (viewMode === 'tasks') {
        const data = await api.getCalendarData(year, month);
        setCalendarData(data);
      } else if (viewMode === 'preshift') {
        const dates = await api.getPreShiftFormDates(year, month);
        setPreshiftDates(dates);
      } else if (viewMode === 'mod') {
        const dates = await api.getMODReportDates(year, month);
        setModDates(dates);
      } else if (viewMode === 'groupresumes') {
        const dates = await api.getGroupResumeDates(year, month);
        setGroupResumeDates(dates);
      }
    } catch (error) {
      console.error('Error loading calendar data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDateClick = (dateStr) => {
    if (viewMode === 'groupresumes' && selectionMode) {
      // Toggle date selection
      if (selectedDates.includes(dateStr)) {
        setSelectedDates(selectedDates.filter(d => d !== dateStr));
      } else {
        setSelectedDates([...selectedDates, dateStr].sort());
      }
      return;
    }

    if (viewMode === 'preshift') {
      setSelectedDate(dateStr);
      setShowPreShiftForm(true);
    } else if (viewMode === 'mod') {
      setSelectedDate(dateStr);
      setShowMODReport(true);
    } else if (viewMode === 'groupresumes') {
      setSelectedDate(dateStr);
      setShowGroupResumeList(true);
    } else {
      onDateSelect(dateStr);
    }
  };

  const handleClosePreShiftForm = () => {
    setShowPreShiftForm(false);
    setSelectedDate(null);
    loadCalendarData();
  };

  const handleCloseMODReport = () => {
    setShowMODReport(false);
    setSelectedDate(null);
    loadCalendarData();
  };

  const handleCloseGroupResumeList = () => {
    setShowGroupResumeList(false);
    setSelectedDate(null);
    loadCalendarData();
  };

  const startSelectionMode = () => {
    setSelectionMode(true);
    setSelectedDates([]);
  };

  const cancelSelection = () => {
    setSelectionMode(false);
    setSelectedDates([]);
  };

  const generatePacket = async () => {
    if (selectedDates.length === 0) {
      alert('Please select at least one date');
      return;
    }

    setGeneratingPacket(true);
    try {
      await api.generateGroupResumePacket(selectedDates);
      alert('Packet generated successfully!');
      setSelectionMode(false);
      setSelectedDates([]);
    } catch (error) {
      console.error('Error generating packet:', error);
      alert('Error generating packet. Please try again.');
    } finally {
      setGeneratingPacket(false);
    }
  };

  const getColor = (percentage) => {
    if (percentage >= 90) return 'green';
    if (percentage >= 50) return 'yellow';
    if (percentage > 0) return 'red';
    return 'gray';
  };

  const getBackgroundColor = (percentage) => {
    if (percentage >= 90) return '#d4edda';
    if (percentage >= 50) return '#fff3cd';
    if (percentage > 0) return '#f8d7da';
    return 'white';
  };

  const getDaysInMonth = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);

    const days = [];
    const startingDayOfWeek = firstDay.getDay();
    const daysInMonth = lastDay.getDate();

    const prevMonth = new Date(year, month, 0);
    const daysInPrevMonth = prevMonth.getDate();

    for (let i = startingDayOfWeek - 1; i >= 0; i--) {
      const day = daysInPrevMonth - i;
      const date = new Date(year, month - 1, day);
      days.push({ date, isCurrentMonth: false });
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      days.push({ date, isCurrentMonth: true });
    }

    const remainingDays = 42 - days.length;
    for (let day = 1; day <= remainingDays; day++) {
      const date = new Date(year, month + 1, day);
      days.push({ date, isCurrentMonth: false });
    }

    return days;
  };

  const getWeekStart = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day;
    d.setDate(diff);
    return d.toISOString().split('T')[0];
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const hasPreShiftForm = (dateStr) => {
    return preshiftDates.includes(dateStr);
  };

  const hasMODReport = (dateStr) => {
    return modDates.includes(dateStr);
  };

  const getGroupResumeCount = (dateStr) => {
    return groupResumeDates[dateStr] || 0;
  };

  if (showPreShiftForm && selectedDate) {
    return (
      <PreShiftForm 
        selectedDate={selectedDate}
        onClose={handleClosePreShiftForm}
      />
    );
  }

  if (showMODReport && selectedDate) {
    return (
      <MODReport 
        selectedDate={selectedDate}
        onClose={handleCloseMODReport}
      />
    );
  }

  if (showGroupResumeList && selectedDate) {
    return (
      <GroupResumeList 
        selectedDate={selectedDate}
        onClose={handleCloseGroupResumeList}
        userRole={userRole}
      />
    );
  }

  if (loading) {
    return <div className="loading">Loading calendar...</div>;
  }

  const days = getDaysInMonth();
  const today = new Date().toISOString().split('T')[0];

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Calendar View</h1>
        <p>Track team performance, pre-shift forms, MOD reports, and group resumes</p>
      </div>

      <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', alignItems: 'center' }}>
        <label style={{ fontWeight: '600' }}>View:</label>
        <select
          className="form-control"
          value={viewMode}
          onChange={(e) => {
            setViewMode(e.target.value);
            setSelectionMode(false);
            setSelectedDates([]);
          }}
          style={{ width: '200px' }}
        >
          <option value="tasks">Task Calendar</option>
          <option value="preshift">Pre-Shift Forms</option>
          <option value="mod">MOD Reports</option>
          <option value="groupresumes">Group Resumes</option>
        </select>

        {viewMode === 'groupresumes' && canCreatePacket && !selectionMode && (
          <button className="btn btn-primary" onClick={startSelectionMode}>
            📦 Select Dates for Packet
          </button>
        )}

        {selectionMode && (
          <>
            <button 
              className="btn btn-success" 
              onClick={generatePacket}
              disabled={selectedDates.length === 0 || generatingPacket}
            >
              {generatingPacket ? '⏳ Generating...' : `✓ Generate Packet (${selectedDates.length} dates)`}
            </button>
            <button className="btn btn-secondary" onClick={cancelSelection}>
              Cancel
            </button>
          </>
        )}
      </div>

      {selectionMode && (
        <div style={{ 
          padding: '15px', 
          backgroundColor: '#e3f2fd', 
          borderRadius: '8px', 
          marginBottom: '20px',
          border: '2px solid #1976d2'
        }}>
          <p style={{ margin: 0, fontWeight: '600', color: '#1976d2' }}>
            📦 Selection Mode: Click dates to add to packet. Selected: {selectedDates.length} date{selectedDates.length !== 1 ? 's' : ''}
          </p>
        </div>
      )}

      <div className="calendar-container">
        <div className="calendar-header">
          <div className="calendar-nav">
            <button onClick={prevMonth}>← Previous</button>
            <span className="calendar-title">
              {currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
            </span>
            <button onClick={nextMonth}>Next →</button>
          </div>
        </div>

        <div className="calendar-grid">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="calendar-day-header">{day}</div>
          ))}

          {days.map((dayObj, index) => {
            const dateStr = dayObj.date.toISOString().split('T')[0];
            const isToday = dateStr === today;
            const isPast = new Date(dateStr) <= new Date(today);
            const isSelected = selectedDates.includes(dateStr);

            if (viewMode === 'tasks') {
              const dayData = calendarData?.daily?.[dateStr] || { percentage: 0 };
              const weekStart = getWeekStart(dayObj.date);
              const weekData = calendarData?.weekly?.[weekStart] || { percentage: 0 };
              const backgroundColor = dayObj.isCurrentMonth && isPast ? getBackgroundColor(dayData.percentage) : 'white';

              return (
                <div
                  key={index}
                  className={`calendar-day ${!dayObj.isCurrentMonth ? 'other-month' : ''} ${isToday ? 'today' : ''}`}
                  onClick={() => dayObj.isCurrentMonth && isPast && handleDateClick(dateStr)}
                  style={{ 
                    cursor: dayObj.isCurrentMonth && isPast ? 'pointer' : 'default',
                    backgroundColor: backgroundColor
                  }}
                >
                  {dayObj.isCurrentMonth && isPast && (
                    <div className={`weekly-indicator ${getColor(weekData.percentage)}`} />
                  )}
                  <div className="day-number">{dayObj.date.getDate()}</div>
                  {dayObj.isCurrentMonth && isPast && (
                    <div className="day-completion">
                      {dayData.percentage}% complete
                    </div>
                  )}
                </div>
              );
            } else if (viewMode === 'preshift') {
              const hasFilled = hasPreShiftForm(dateStr);

              return (
                <div
                  key={index}
                  className={`calendar-day ${!dayObj.isCurrentMonth ? 'other-month' : ''} ${isToday ? 'today' : ''}`}
                  onClick={() => dayObj.isCurrentMonth && handleDateClick(dateStr)}
                  style={{ 
                    cursor: dayObj.isCurrentMonth ? 'pointer' : 'default',
                    backgroundColor: hasFilled ? '#d4edda' : 'white'
                  }}
                >
                  <div className="day-number">{dayObj.date.getDate()}</div>
                  {dayObj.isCurrentMonth && hasFilled && (
                    <div style={{
                      fontSize: '12px',
                      color: '#27ae60',
                      fontWeight: '600',
                      marginTop: '5px'
                    }}>
                      ✓ Filled
                    </div>
                  )}
                </div>
              );
            } else if (viewMode === 'mod') {
              const hasFilled = hasMODReport(dateStr);

              return (
                <div
                  key={index}
                  className={`calendar-day ${!dayObj.isCurrentMonth ? 'other-month' : ''} ${isToday ? 'today' : ''}`}
                  onClick={() => dayObj.isCurrentMonth && handleDateClick(dateStr)}
                  style={{ 
                    cursor: dayObj.isCurrentMonth ? 'pointer' : 'default',
                    backgroundColor: hasFilled ? '#d4edda' : 'white'
                  }}
                >
                  <div className="day-number">{dayObj.date.getDate()}</div>
                  {dayObj.isCurrentMonth && hasFilled && (
                    <div style={{
                      fontSize: '12px',
                      color: '#27ae60',
                      fontWeight: '600',
                      marginTop: '5px'
                    }}>
                      ✓ Filled
                    </div>
                  )}
                </div>
              );
            } else {
              // Group Resumes mode
              const groupCount = getGroupResumeCount(dateStr);
              let backgroundColor = groupCount > 0 ? '#e3f2fd' : 'white';
              if (isSelected) {
                backgroundColor = '#1976d2';
              }

              return (
                <div
                  key={index}
                  className={`calendar-day ${!dayObj.isCurrentMonth ? 'other-month' : ''} ${isToday ? 'today' : ''}`}
                  onClick={() => dayObj.isCurrentMonth && handleDateClick(dateStr)}
                  style={{ 
                    cursor: dayObj.isCurrentMonth ? 'pointer' : 'default',
                    backgroundColor: backgroundColor,
                    border: isSelected ? '3px solid #0d47a1' : undefined
                  }}
                >
                  <div className="day-number" style={{ color: isSelected ? 'white' : undefined }}>
                    {dayObj.date.getDate()}
                  </div>
                  {dayObj.isCurrentMonth && groupCount > 0 && (
                    <div style={{
                      fontSize: '12px',
                      color: isSelected ? 'white' : '#1976d2',
                      fontWeight: '600',
                      marginTop: '5px'
                    }}>
                      {isSelected && '✓ '}{groupCount} {groupCount === 1 ? 'Group' : 'Groups'}
                    </div>
                  )}
                </div>
              );
            }
          })}
        </div>

        {viewMode === 'tasks' && (
          <div className="calendar-legend">
            <div className="legend-item">
              <div className="legend-color green"></div>
              <span>90%+ Complete</span>
            </div>
            <div className="legend-item">
              <div className="legend-color yellow"></div>
              <span>50-89% Complete</span>
            </div>
            <div className="legend-item">
              <div className="legend-color red"></div>
              <span>Below 50%</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default CalendarView;
